# Fetch all phone friend emails (paginate if needed)
phone_friend_emails = set()
page_index = 0
while True:
    contacts = apis.phone.search_contacts(access_token=phone_token, relationship='friend', page_index=page_index, page_limit=100)
    if not contacts:
        break
    for c in contacts:
        phone_friend_emails.add(c['email'])
    if len(contacts) < 100:
        break
    page_index += 1
print("Phone friend emails:", phone_friend_emails)

# Fetch all phone friend emails with proper pagination (page_limit max 20)
phone_friend_emails = set()
