steps.code:
# Final verification: ensure no playlist (other than Archived Songs) contains any of the matched songs
matched_set = set(matched_song_ids)
remaining = []
for pl in all_playlists:
    pl_id = pl['playlist_id']
    pl_info = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_token)
    pl_song_ids = [song['id'] for song in pl_info['songs']]
    overlap = matched_set.intersection(pl_song_ids)
    if overlap:
        remaining.append((pl['title'], pl_id, sorted(overlap)))

if remaining:
    print("WARNING: Songs still present in other playlists:")
    for title, pid, ids in remaining:
        print(f"  {title} (id={pid}): {ids}")
else:
    print("All matched songs have been removed from all playlists and are only in 'Archived Songs'.")

