# Search for each song in the archive list and collect their song IDs
archive_song_ids = []
for title, artist in songs_to_archive:
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=login_result["access_token"], page_limit=20)
    # Find the exact match by title and artist
    found = None
    for song in results:
        if song["title"] == title:
            # Check if any artist matches
            for art in song["artists"]:
                if art["name"] == artist:
                    found = song["song_id"]
                    break
            if found:
                break
    if found:
        archive_song_ids.append(found)
        print(f"Found: {title} by {artist} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print("Archive song IDs:", archive_song_ids)

# Search for all songs in the archive list and collect their song IDs
archived_song_ids = []
for title, artist in songs_to_archive:
    query = f"{title} {artist}"
    results = apis.spotify.search_songs(query=query, access_token=login_result["access_token"])
    # Find exact match
    found = None
    for song in results:
        if song["title"].lower() == title.lower():
            # Check if artist matches
            for art in song["artists"]:
                if art["name"].lower() == artist.lower():
                    found = song["song_id"]
                    break
            if found:
                break
    if found:
        archived_song_ids.append(found)
        print(f"Found: {title} by {artist} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print("All archived song IDs:", archived_song_ids)

# Create the "Old Songs" playlist if it doesn't exist
old_songs_playlist = None
for pl in all_playlists:
    if pl["title"] == "Old Songs":
        old_songs_playlist = pl
        break

if old_songs_playlist is None:
    create_result = apis.spotify.create_playlist(title="Old Songs", access_token=login_result["access_token"])
    print("Create result:", create_result)
    old_songs_playlist_id = create_result["playlist_id"]
else:
    old_songs_playlist_id = old_songs_playlist["playlist_id"]

print("Old Songs playlist ID:", old_songs_playlist_id)

# Check if we already created the "Old Songs" playlist
if 'create_result' in globals():
    print("create_result exists:", create_result)
else:
    print("create_result not defined yet")

