print("Missing from Old Songs:", missing)
if missing:
    for song_id in missing:
        result = apis.spotify.add_song_to_playlist(playlist_id=654, song_id=song_id, access_token=login_result["access_token"])
        print(f"Added song_id {song_id}: {result}")
else:
    print("All archived songs are present in Old Songs.")

# Re-fetch all playlists to verify no archived songs remain and check "Old Songs" playlist
all_playlists = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    all_playlists.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Identify the "Old Songs" playlist
old_songs_playlist = next((p for p in all_playlists if p["title"] == "Old Songs"), None)
print("Old Songs playlist:", old_songs_playlist)

# Check for any remaining archived songs in other playlists
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
remaining = []
for p in all_playlists:
    if p["playlist_id"] == old_songs_playlist["playlist_id"]:
        continue
    for song_id in p["song_ids"]:
        if song_id in archived_song_ids:
            remaining.append((p["playlist_id"], p["title"], song_id))

print("Remaining archived songs in other playlists:", remaining)

