# Let's search for each old song and find the exact match by title and artists.
old_song_ids = []
for song in old_songs:
    results = apis.spotify.search_songs(query=song['title'], access_token=spotify_login['access_token'])
    # Find exact match: title matches and all artists match
    found = None
    for r in results:
        if r['title'].lower() == song['title'].lower():
            # Check artists
            result_artists = [a['name'].lower() for a in r['artists']]
            expected_artists = [a.lower() for a in song['artists']]
            if set(result_artists) == set(expected_artists):
                found = r
                break
    if found:
        old_song_ids.append(found['song_id'])
        print(f"Found: {song['title']} -> ID {found['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']}")

print(f"Total old songs found: {len(old_song_ids)}")

