# Let's search by title with spaces and then match by artist
song_id_map = {}

for title, artists in songs_to_archive:
    # Search with title only
    results = apis.spotify.search_songs(query=title, access_token=spotify_token)
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            song_artists = [a['name'] for a in song['artists']]
            expected_artists = [a.strip() for a in artists.split(',')]
            # Check if all expected artists are in song_artists (case insensitive)
            if all(any(exp.lower() == sa.lower() for sa in song_artists) for exp in expected_artists) and len(song_artists) == len(expected_artists):
                found = song
                break
    if found:
        song_id_map[(title, artists)] = found['song_id']
        print(f"Found: {title} by {artists} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artists}")

print(f"Total found: {len(song_id_map)}")

