import json

# We'll create a function to search and get the exact song_id
def get_song_id(title, artists):
    # Build query: title and artists concatenated without spaces
    query = title.replace(" ", "") + "".join(a.replace(" ", "") for a in artists)
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find the exact match
    for song in results:
        if song['title'].lower() == title.lower():
            song_artists = [a['name'] for a in song['artists']]
            if sorted(song_artists) == sorted(artists):
                return song['song_id']
    return None

# Build mapping
song_id_map = {}
for song in songs_to_archive:
    sid = get_song_id(song['title'], song['artists'])
    if sid is not None:
        song_id_map[(song['title'], tuple(song['artists']))] = sid
    else:
        print(f"Could not find song: {song['title']} by {song['artists']}")

print("Song ID map:", song_id_map)
print("Number of songs mapped:", len(song_id_map))

