# We need to handle the case where a song was already removed (like 295 from playlist 513).
# We'll attempt removal and only add to the new playlist if removal succeeds.
added_songs = {295}  # already added

for pl in playlists:
    pl_id = pl['playlist_id']
    for sid in pl['song_ids']:
        if sid in target_song_ids:
            try:
                apis.spotify.remove_song_from_playlist(playlist_id=pl_id, song_id=sid, access_token=spotify_token)
                print(f"Removed {sid} from playlist {pl_id}")
                if sid not in added_songs:
                    apis.spotify.add_song_to_playlist(playlist_id=654, song_id=sid, access_token=spotify_token)
                    added_songs.add(sid)
                    print(f"Added {sid} to playlist 654")
            except Exception as e:
                print(f"Could not remove {sid} from playlist {pl_id}: {e}")

