# Update the note content with release months
new_lines = []
for line in note['content'].split('\n'):
    if line.strip().startswith('- '):
        # Parse the line
        line_stripped = line.strip()[2:]  # remove "- "
        if ' BY ' in line_stripped:
            title_part, artists_part = line_stripped.split(' BY ', 1)
            if ' RELEASED_AT ' in artists_part:
                artists_str, released = artists_part.split(' RELEASED_AT ', 1)
            else:
                artists_str = artists_part
                released = None
            title = title_part.strip()
            artists = [a.strip() for a in artists_str.split(',')]
            if released == 'TODO':
                key = (title, tuple(artists))
                if key in release_map:
                    new_released = release_map[key]
                    # Replace the TODO with the actual month/year
                    new_line = f"- {title} BY {artists_str} RELEASED_AT {new_released}"
                    new_lines.append(new_line)
                else:
                    print(f"WARNING: No release month for {title} by {artists}")
                    new_lines.append(line)  # keep as is
            else:
                new_lines.append(line)  # already has release month
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

