# Fetch all liked songs to verify none remain in the queue
liked_songs_all = []
page_index = 0
while True:
    page = apis.spotify.show_liked_songs(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    liked_songs_all.extend(page)
    page_index += 1

liked_ids = {song['song_id'] for song in liked_songs_all}
queue_ids = {song['song_id'] for song in queue_after}
remaining_liked_in_queue = liked_ids & queue_ids
print("Liked songs in queue after removal:", remaining_liked_in_queue)

